// countPairsWithSum(nums, target) → { count, lookups }
//   count   = nombre de paires (i<j) avec nums[i]+nums[j] === target ;
//   lookups = nombre de CONSULTATIONS faites pour trouver les compléments.
// BASELINE (ci-dessous) : double boucle O(n²) — correcte, mais lookups explose
// (n(n-1)/2). HYPOTHÈSE : une Map complément→occurrences ramène à UNE consultation
// par élément → lookups = n. Objectif : même count, lookups = n.
export function countPairsWithSum(nums, target) {
  let count = 0;
  let lookups = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      lookups++; // compare chaque paire : O(n²)
      if (nums[i] + nums[j] === target) count++;
    }
  }
  return { count, lookups };
}

